function getUrl(tile, ctx) {
  // Alaska and the Aleutians are left out: the service shows a copyrighted mosaic there, not public-domain imagery.
  var s = tile.latBottom, n = tile.latTop, w = tile.lonLeft, e = tile.lonRight;
  if (n > 54.5 && s < 71.5 && w < -129.2) return '';
  if (n > 51.1 && s < 54.5 && w < -162.0) return '';
  if (n > 51.3 && s < 53.1 && e > 172.3) return '';
  return template(ctx.urlBase);
}
